der Goldschmied benötigt, um den Ring zu schmieden. "}]}],"id":"066f59ba-58fe-471a-ae1b-a17db40afc5d"}],"id":"893ad140-fad1-443d-a9b1-c60261be9d08"},"solution":{"plugin":"solution","state":{"prerequisite":{"id":"1555","title":"Volumenberechnung Zylinder"},"strategy":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"27b92e6c-2bde-4b7e-9ab7-5f2dac04fcba"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Zuerst solltest du das Volumen der beiden Zylinder (Außen und Innendurchmesser) berechnen. "}]},{"type":"p","children":[{"text":"Dann kannst du das Volumen im Inneren von dem des äußeren abziehen und erhältst das Volumen des Rings. "}]}],"id":"40d0cd5e-ef70-4369-ad80-ab8352d8af0f"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Das Volumen im "},{"text":"Inneren","strong":true},{"text":" lässt sich mit der Volumenformel für Zylinder berechen."}]}],"id":"4738fbb3-fcb0-4d6c-bbce-7ad3d2d1594a"},{"plugin":"text","state":[{"type":"p","children":[{"text":""},{"type":"math","src":"V_\text{innen} = r^2 \cdot \pi \cdot h","inline":true,"children":[{"text":"V"}]},{"text":""}]}],"id":"210886e6-d416-4537-8308-b1810158ae7b"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Dabei ist "},{"type":"math","src":"r = \dfrac{1{,}8\text{ cm}}{2}=0{,}9\text{ cm}","inline":true,"children":[{"text":"r ="}]},{"text":""}]}],"id":"3056a073-7b0b-4a7a-b717-d32c095dc741"},{"plugin":"text","state":[{"type":"p","children":[{"text":"und "},{"type":"math","src":"h =0{,}8 \text{ cm}","inline":true,"children":[{"text":"h ="}]},{"text":"."}]}],"id":"86e1be1c-8877-4402-949c-2ca3d5d19164"},{"plugin":"text","state":[{"type":"p","children":[{"text":""},{"type":"math","src":"\begin{array}{rcl}
